    (hu : F.SeqCauchy u) {n m : Nat} (hnm : n <= m) :
    F.le (lower F hu n) (lower F hu m)

theorem upper_antitone {u : Nat -> alpha}
    (hu : F.SeqCauchy u) {n m : Nat} (hnm : n <= m) :
    F.le (upper F hu m) (upper F hu n)

theorem bandLower_le_lower {u : Nat -> alpha}
    (hu : F.SeqCauchy u) (k : Nat) :
    F.le (bandLower F hu k) (lower F hu k)

theorem upper_le_bandUpper {u : Nat -> alpha}
    (hu : F.SeqCauchy u) (k : Nat) :
    F.le (upper F hu k) (bandUpper F hu k)

theorem length_nonneg {u : Nat -> alpha}
    (hu : F.SeqCauchy u) (k : Nat) :
    F.le F.zero (length F hu k)

theorem nested_intervals {u : Nat -> alpha}
    (hu : F.SeqCauchy u) :
    F.NestedClosedIntervals (lower F hu) (upper F hu)

theorem lower_endpoints_bounded_above {a b : Nat -> alpha}
    (hnest : F.NestedClosedIntervals a b) :
    F.SeqBoundedAbove a

theorem eventually_subsequence_of_eventually {phi : Nat -> Nat}
    {P : Nat -> Prop}
    (hphi : SubsequenceIndex phi)
    (hP : Eventually P) :
    Eventually (fun n : Nat => P (phi n))

theorem seqCauchy_eventually_upper {u : Nat -> alpha}
    (hu : F.SeqCauchy u) :
    Exists (fun B : alpha => Eventually (fun n : Nat => F.le (u n) B))

theorem seqCauchy_eventually_lower {u : Nat -> alpha}
    (hu : F.SeqCauchy u) :
    Exists (fun B : alpha => Eventually (fun n : Nat => F.le B (u n)))

theorem seqTendsto_of_cauchy_subsequence {u : Nat -> alpha}
    {phi : Nat -> Nat} {l : alpha}
    (hu : F.SeqCauchy u)
    (hphi : SubsequenceIndex phi)
    (hsub : F.SeqTendsto (subsequence u phi) l) :
    F.SeqTendsto u l

theorem add_le_of_sub_le {x y eps : alpha}
    (h : F.le eps (F.sub y x)) :
    F.le (F.add x eps) y

theorem seqCauchy_of_neg_seqCauchy {u : Nat -> alpha}
    (hv : F.SeqCauchy (fun n : Nat => F.neg (u n))) :
    F.SeqCauchy u

theorem eventual_lower_nonempty_of_cauchy {u : Nat -> alpha}
    (hu : (F C).SeqCauchy u) :
    Exists (EventualLowerBound C u)

theorem eventual_lower_bounded_above_of_cauchy {u : Nat -> alpha}
    (hu : (F C).SeqCauchy u) :
    Exists (IsUpperBound (F C).le (EventualLowerBound C u))

theorem limitCandidate_tendsto {u : Nat -> alpha}
    (hu : (F C).SeqCauchy u) :
    (F C).SeqTendsto u (limitCandidate C hu)
